INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_BAHAI','Bahá''í Era (Badí'')',1844,2025)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_SMITH_BAHAI','secondary scholarship','Peter Smith, An Introduction to the Bahá''í Faith (Cambridge University Press, 2008)','Authoritative scholarly survey of Bahá''í history, central figures, theology of progressive revelation, and administrative institutions.'),
 ('SRC_BAHAI_KITAB_AQDAS','primary text','Bahá''u''lláh, Kitáb-i-Aqdas (The Most Holy Book), Bahá''í World Centre edition','Central book of Bahá''í laws and covenant, including provisions establishing the Universal House of Justice.'),
 ('SRC_BAHAI_KITAB_IQAN','primary text','Bahá''u''lláh, Kitáb-i-Íqán (The Book of Certitude), Bahá''í World Centre edition','Doctrinal exposition of progressive revelation and the station of the Manifestations of God in relation to prior prophets.'),
 ('SRC_SHOGHI_GPB','primary text','Shoghi Effendi, God Passes By (Bahá''í Publishing Trust, 1944)','Authoritative Bahá''í history of the first Bahá''í century covering the Báb, Bahá''u''lláh, Abdu''l-Bahá and institutional development.')
INSERT INTO _e VALUES
 ('ENT_BAH_MANIFESTATIONS','Manifestations of God (collective)','Collective/divine category','Collective','Bahá''í','progressive revelation; prophethood; divine mediation','B','Bahá''í doctrinal category (Mazhar-i-Iláhí) for the succession of supreme Messengers; serves as the cohort hub. Attested across Bahá''u''lláh''s Kitáb-i-Íqán and Smith (2008).'),
 ('ENT_BAH_MAZHAR','Manifestation of God (Mazhar)','Theological concept','Theological concept','Bahá''í','prophetology; divine mediation; revelation','B','Core Bahá''í concept: a perfect mirror reflecting divine attributes who founds a religious dispensation. Attested in Kitáb-i-Íqán; Smith (2008) ch. on theology.'),
 ('ENT_BAH_BAB','The Báb (Siyyid Alí-Muhammad Shírází)','Manifestation/Prophet-founder','Manifestation/Prophet-founder','Bahá''í','revelation; herald; martyrdom','B','1819-1850; herald-Manifestation who declared his mission in 1844 (start of the Bahá''í era) and prophesied ''Him Whom God shall make manifest.'' Historically attested; Smith (2008); Shoghi Effendi, God Passes By.'),
 ('ENT_BAH_BAHAULLAH','Bahá''u''lláh (Mírzá Husayn-Alí Núrí)','Manifestation/Prophet-founder','Manifestation/Prophet-founder','Bahá''í','revelation; covenant; central authority','B','1817-1892; central figure and founder of the Bahá''í Faith, ''Him Whom God shall make manifest,'' author of the Kitáb-i-Aqdas and Kitáb-i-Íqán. Historically attested; Smith (2008).'),
 ('ENT_BAH_ABDULBAHA','Abdu''l-Bahá (Abbás Effendi)','Authoritative interpreter/exemplar','Authoritative interpreter/exemplar','Bahá''í','interpretation; exemplar; covenant','B','1844-1921; eldest son of Bahá''u''lláh, appointed Centre of the Covenant and authorized interpreter; not regarded as a Manifestation. Historically attested; Smith (2008).'),
 ('ENT_BAH_SHOGHI','Shoghi Effendi (Shoghi Rabbání)','Guardian/authoritative interpreter','Guardian/authoritative interpreter','Bahá''í','guardianship; interpretation; administration','B','1897-1957; great-grandson of Bahá''u''lláh, Guardian of the Cause and authorized interpreter who built the administrative order. Historically attested; author of God Passes By.'),
 ('ENT_BAH_UHJ','Universal House of Justice','Institution','Institution','Bahá''í','governance; legislation; covenant','B','Supreme elected governing body of the Bahá''í Faith, ordained in the Kitáb-i-Aqdas and first elected 1963; seated in Haifa. Attested in primary scripture and Smith (2008).'),
 ('ENT_BAH_COVENANT','Covenant (Bahá''í)','Theological concept','Theological concept','Bahá''í','succession; authority; unity','B','Bahá''í concept of the binding chain of authority from Bahá''u''lláh through Abdu''l-Bahá, the Guardianship and the Universal House of Justice. Attested in Kitáb-i-Aqdas and Smith (2008).'),
 ('ENT_BAH_QUDDUS','Quddús (Mullá Muhammad-Alí Bárfurúshí)','Disciple/saint','Disciple/saint','Bahá''í','discipleship; martyrdom','C','d. 1849; foremost of the Báb''s Letters of the Living and leading figure at the Shaykh Tabarsí upheaval. Historically attested; Shoghi Effendi, God Passes By.'),
 ('ENT_BAH_TAHIRIH','Táhirih (Fátimih Baraghání, Qurratu''l-Ayn)','Disciple/saint','Disciple/saint','Bahá''í','discipleship; poetry; martyrdom; women''s emancipation','C','1817-1852; only woman among the Báb''s Letters of the Living, poet and reformer martyred for the Bábí cause. Historically attested; Smith (2008).'),
 ('ENT_BAH_LETTERS_LIVING','Letters of the Living (Hurúf-i-Hayy)','Collective/disciple body','Collective','Bahá''í','discipleship; early Bábí community','C','The eighteen first disciples who independently recognized the Báb, forming with him the first ''Unity.'' Attested in Shoghi Effendi, God Passes By.'),
 ('ENT_BAH_HANDS_CAUSE','Hands of the Cause of God','Institution/office','Institution/office','Bahá''í','propagation; protection of the Faith','C','Distinguished believers appointed to propagate and protect the Faith; functioned especially under Shoghi Effendi and after his passing. Attested in Smith (2008).'),
 ('ENT_BAH_BAYAN','Bayán (Báb''s revelation)','Scripture/concept','Scripture/concept','Bahá''í','scripture; messianic prophecy','C','Principal scriptural work of the Báb (Persian and Arabic Bayán) which abrogated Islamic law and foretold the coming Manifestation. Attested in Smith (2008).');
