INSERT INTO _r VALUES
 ('ENT_BAH_MAZHAR','member_of','ENT_BAH_MANIFESTATIONS','high','The concept of the Manifestation of God defines the membership category that the collective hub gathers.'),
 ('ENT_BAH_BAB','member_of','ENT_BAH_MANIFESTATIONS','high','The Báb is regarded in Bahá''í doctrine as an independent Manifestation of God.'),
 ('ENT_BAH_BAHAULLAH','member_of','ENT_BAH_MANIFESTATIONS','high','Bahá''u''lláh is the central Manifestation of God of the present dispensation.'),
 ('ENT_BAH_BAB','embodies','ENT_BAH_MAZHAR','high','The Báb is an instance of the Mazhar (Manifestation of God) category in Bahá''í prophetology.'),
 ('ENT_BAH_BAHAULLAH','embodies','ENT_BAH_MAZHAR','high','Bahá''u''lláh is the supreme exemplar of the Mazhar category for this age.'),
 ('ENT_BAH_BAB','reveals','ENT_BAH_BAYAN','high','The Báb is the author/revealer of the Bayán.'),
 ('ENT_BAH_BAYAN','revealed_by','ENT_BAH_BAB','high','The Bayán is the scriptural corpus revealed through the Báb (inverse of the reveals edge; replaces an incorrect reception_of).'),
 ('ENT_BAH_QUDDUS','member_of','ENT_BAH_LETTERS_LIVING','high','Quddús was the eighteenth and foremost of the Letters of the Living.'),
 ('ENT_BAH_TAHIRIH','member_of','ENT_BAH_LETTERS_LIVING','high','Táhirih was the only woman among the Letters of the Living.'),
 ('ENT_BAH_QUDDUS','associated_with','ENT_BAH_BAB','high','Quddús was a leading disciple of the Báb.'),
 ('ENT_BAH_TAHIRIH','associated_with','ENT_BAH_BAB','high','Táhirih was an early recognizer and disciple of the Báb.'),
 ('ENT_BAH_ABDULBAHA','child_of','ENT_BAH_BAHAULLAH','high','Abdu''l-Bahá was the eldest son of Bahá''u''lláh.'),
 ('ENT_BAH_BAHAULLAH','parent_of','ENT_BAH_ABDULBAHA','high','Bahá''u''lláh was the father of Abdu''l-Bahá.'),
 ('ENT_BAH_ABDULBAHA','associated_with','ENT_BAH_COVENANT','high','Abdu''l-Bahá was appointed Centre of the Covenant by Bahá''u''lláh.'),
 ('ENT_BAH_SHOGHI','associated_with','ENT_BAH_COVENANT','high','Shoghi Effendi was appointed Guardian and authorized interpreter within the line of the Covenant.'),
 ('ENT_BAH_SHOGHI','associated_with','ENT_BAH_ABDULBAHA','high','Shoghi Effendi was appointed Guardian by Abdu''l-Bahá''s Will and Testament.'),
 ('ENT_BAH_COVENANT','emanates_from','ENT_BAH_BAHAULLAH','high','The Bahá''í Covenant derives its authority from Bahá''u''lláh''s appointment of successors (replaces an incorrect reception_of).'),
 ('ENT_BAH_UHJ','associated_with','ENT_BAH_BAHAULLAH','high','The Universal House of Justice was ordained by Bahá''u''lláh in the Kitáb-i-Aqdas (replaces an incorrect reception_of).'),
 ('ENT_BAH_UHJ','associated_with','ENT_BAH_COVENANT','high','The Universal House of Justice is the institution charged with the Covenant after the Guardianship.'),
 ('ENT_BAH_HANDS_CAUSE','associated_with','ENT_BAH_SHOGHI','medium','The Hands of the Cause functioned prominently under Shoghi Effendi''s guidance.'),
 ('ENT_BAH_BAHAULLAH','reception_of','ENT_BAH_BAB','high','Bahá''u''lláh is identified by Bahá''ís as the fulfillment of the Báb''s prophecy of ''Him Whom God shall make manifest.'''),
 ('ENT_BAH_BAHAULLAH','reception_of','ENT_ISR_ABRAHAM','high','Bahá''í progressive revelation regards Bahá''u''lláh''s dispensation as renewing the religion of prior Manifestations including Abraham.'),
 ('ENT_BAH_BAHAULLAH','reception_of','ENT_ISR_MOSES','high','Bahá''í doctrine treats Moses as a prior Manifestation whose revelation is fulfilled in Bahá''u''lláh''s.'),
 ('ENT_BAH_BAHAULLAH','reception_of','ENT_JESUS_CHRIST','high','Bahá''ís regard Jesus as a Manifestation of God whose return is realized spiritually in Bahá''u''lláh''s revelation.'),
 ('ENT_BAH_BAHAULLAH','reception_of','ENT_ISL_MUHAMMAD','high','Bahá''í teaching honors Muhammad as a Manifestation of God preceding Bahá''u''lláh in the prophetic chain.'),
 ('ENT_BAH_BAHAULLAH','reception_of','ENT_ZOR_ZARATHUSTRA','high','Bahá''í progressive revelation counts Zoroaster among the prior Manifestations of God.'),
 ('ENT_BAH_BAB','aligned_with','ENT_ISL_MAHDI','medium','Bahá''ís hold the Báb fulfilled Shi''i expectation of the return of the Hidden Imam (Mahdi); functional/eschatological alignment, not identity.'),
 ('ENT_BAH_MANIFESTATIONS','associated_with','ENT_BAH_MAZHAR','high','The collective of Manifestations is constituted by the Mazhar prophetological concept.');
